SELECT order_id, order_sn, user_id, total_amount, pay_amount, status, receiver_name, receiver_phone, receiver_address, created_at, updated_at FROM orders
AND (order_sn LIKE CONCAT('%', #{keyword}, '%') OR receiver_name LIKE CONCAT('%', #{keyword}, '%') OR receiver_phone LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY created_at DESC LIMIT #{offset}, #{limit}

